<script>
import {onMount,onDestroy} from "svelte";
import {params} from "svelte-spa-router";
import {get} from "../lib/api.js";
import {addToast} from "../lib/stores.js";
import {readPreference,savePreference} from "../lib/preferences.js";
import {TYPES,TYPE_LABELS,filterGraph} from "../lib/mapViews.js";
import {buildGroupedGraph} from "../lib/grouping.js";
import {isWorkspaceEscape} from "../lib/workspace.js";
import NetworkMap from "../components/map/NetworkMap.svelte";
import TreeView from "../components/map/TreeView.svelte";
let graph={nodes:[],edges:[]},loading=true,error="",mapComponent,grouping=null,groupingLoading=false,groupingError="",mapExpanded=false;
let root="",types=[...TYPES],query="",members=[],depth="all",viewMode="map",saved=[],selection="",viewName="",chooseMembers=false,memberSearch="",ready=false,lastRouteRoot="";
onMount(async()=>{try{graph=await get("/map/graph"); const stored=readPreference("hlh.mapViews",[]);saved=Array.isArray(stored)?stored.filter(v=>v&&typeof v.id==="string"&&typeof v.name==="string"):[];
 const prefs=readPreference("hlh.mapCurrent",null);if(prefs)apply(prefs);if($params?.root){root=$params.root;members=[];}lastRouteRoot=$params?.root||"";ready=true;}catch(e){error=e.message;}finally{loading=false;}});
$: if(ready && ($params?.root||"")!==lastRouteRoot){lastRouteRoot=$params?.root||"";if(lastRouteRoot){root=lastRouteRoot;members=[];selection="";}}
async function loadGrouping(){groupingLoading=true;groupingError="";try{grouping=await get("/container-groups/effective");}catch(e){groupingError=e.message;}finally{groupingLoading=false;}}
$: if(ready&&viewMode==="grouped"&&!grouping&&!groupingLoading&&!groupingError)loadGrouping();
$: hosts=graph.nodes.filter(n=>n.data.type==="hardware");
$: filtered=filterGraph(graph,{root,types,query,members,depth});
$: groupedGraph=grouping?buildGroupedGraph(filtered,grouping):null;
$: hostName=root?(hosts.find(n=>n.data.id===root)?.data.rawName||"Selected host"):"All hosts";
$: contextLabel=`${hostName}${query.trim()?` · search “${query.trim()}”`:""}${types.length<TYPES.length?" · filtered types":""} · ${filtered.matches} matches`;
$: presentationLabel=viewMode==="map"?"Graph":viewMode==="grouped"?"Grouped":"Tree";
onMount(()=>{const onKeydown=(event)=>{if(isWorkspaceEscape(event)&&mapExpanded)mapExpanded=false;};window.addEventListener("keydown",onKeydown);return()=>window.removeEventListener("keydown",onKeydown);});
$: if(typeof document!=="undefined")document.body.classList.toggle("map-expanded",mapExpanded);
onDestroy(()=>{if(typeof document!=="undefined")document.body.classList.remove("map-expanded");});
$: signature=JSON.stringify({root,types:[...types].sort(),query,members:[...members].sort(),depth});
$: if(ready)savePreference("hlh.mapCurrent",{root,types,query,members,depth,viewMode});
$: pickerNodes=graph.nodes.filter(n=>(n.data.rawName||n.data.label||"").toLowerCase().includes(memberSearch.toLowerCase()));
function apply(v){root=typeof v.root==="string"?v.root:"";types=Array.isArray(v.types)?v.types.filter(t=>TYPES.includes(t)):[...TYPES];query=typeof v.query==="string"?v.query:"";members=Array.isArray(v.members)?v.members.filter(x=>typeof x==="string"):[];depth=["all","0","1","2"].includes(v.depth)?v.depth:"all";viewMode=["map","grouped","tree"].includes(v.viewMode)?v.viewMode:"map";}
function selectView(){const v=saved.find(x=>x.id===selection);if(v){apply(v);viewName=v.name;}else{apply({});viewName="";}}
function saveView(){if(!viewName.trim()){addToast("Give this map a name first","error");return;}const id=selection||`view-${Date.now()}`;const v={id,name:viewName.trim(),root,types:[...types],query,members:[...members],depth,viewMode};const next=[...saved.filter(x=>x.id!==id),v];if(savePreference("hlh.mapViews",next)){saved=next;selection=id;addToast("Map view saved in this browser","success");}else addToast("Browser storage is unavailable or full","error");}
function deleteView(){if(!selection||!confirm("Delete this saved map view? Inventory records will remain."))return;const next=saved.filter(x=>x.id!==selection);if(savePreference("hlh.mapViews",next)){saved=next;selection="";viewName="";}}
function scopeChanged(){members=[];selection="";if($params?.root)window.location.hash="/map";}
</script>
<div class="map-page"><div class="page-heading"><div><div class="eyebrow">EXPLORE YOUR LAB</div><h1>Maps</h1><p>Focus on a host, filter the inventory, or save a custom selection.</p></div><div class="view-toggle" role="group" aria-label="Map presentation"><button class:active={viewMode==="map"} on:click={()=>viewMode="map"}>Graph</button><button class:active={viewMode==="grouped"} on:click={()=>{groupingError="";viewMode="grouped";}}>Grouped</button><button class:active={viewMode==="tree"} on:click={()=>viewMode="tree"}>Tree</button></div></div>
{#if error}<p role="alert">Could not load maps: {error}</p>{:else if loading}<p>Loading maps…</p>{:else}
<div class="map-toolbar"><label>Saved map<select bind:value={selection} on:change={selectView}><option value="">Unsaved view</option>{#each saved as v}<option value={v.id}>{v.name}</option>{/each}</select></label><label>Top-level host<select bind:value={root} on:change={scopeChanged}><option value="">All hosts</option>{#each hosts as n}<option value={n.data.id}>{n.data.rawName||n.data.label}</option>{/each}</select></label><label>Search names<input type="search" bind:value={query} placeholder="Find an application…" /></label><label>Depth<select bind:value={depth}><option value="all">All levels</option><option value="0">Host only</option><option value="1">One level</option><option value="2">Two levels</option></select></label></div>
<div class="filter-row"><span>Show</span>{#each TYPES as type}<label><input type="checkbox" bind:group={types} value={type}/>{TYPE_LABELS[type]}</label>{/each}</div>
<div class="save-row"><input aria-label="Map name" bind:value={viewName} placeholder="Map name, e.g. Local AI" maxlength="80"/><button on:click={saveView}>Save view</button>{#if selection}<button class="secondary outline" on:click={deleteView}>Delete view</button>{/if}<button class="secondary outline" on:click={()=>chooseMembers=!chooseMembers}>{chooseMembers?"Close selection":"Choose individual devices"}</button><span>{filtered.matches} matches · {filtered.nodes.length} nodes including parent context</span></div>
{#if chooseMembers}<section class="member-picker"><h2>Custom map selection</h2><p>Select records from any host. This replaces the host scope; inventory records are shared across all maps.</p><input aria-label="Find records for custom map" type="search" bind:value={memberSearch} placeholder="Search records…"/><button class="secondary outline" on:click={()=>members=[]}>Clear selection</button><div class="member-list">{#each pickerNodes as n}<label><input type="checkbox" value={n.data.id} bind:group={members}/>{n.data.rawName||n.data.label}<small>{TYPE_LABELS[n.data.type]}</small></label>{/each}</div><small>{members.length} selected. An empty selection uses the host scope.</small></section>{/if}
<p class="view-note">Views and layouts are saved in this browser, separately from inventory exports. Parent nodes remain visible for context. Type names reflect the current inventory model.</p>
{#if viewMode==="grouped"}<p class="view-note">Grouped view groups containers by host. Groups start collapsed; click a group to expand it. “One level” may not show Docker groups because containers are currently at the second hierarchy level.</p>{/if}
<div class="canvas-actions">{#if viewMode!=="tree"}<button class="secondary outline small" on:click={()=>mapComponent?.relayout()}>Auto layout</button><button class="secondary outline small" on:click={()=>mapComponent?.fitView()}>Fit all</button><button class="secondary outline small" on:click={()=>mapComponent?.readableView()}>Readable zoom</button>{/if}<button class="secondary outline small" on:click={()=>mapExpanded=true}>Expand map</button>{#if members.length}<small>Custom selection · {members.length} records</small>{/if}</div>
<div class="map-workspace" class:expanded={mapExpanded}>
{#if mapExpanded}<div class="expanded-toolbar"><button class="secondary outline small" on:click={()=>mapExpanded=false} aria-label="Exit expanded map">Exit</button>{#if viewMode!=="tree"}<button class="secondary outline small" on:click={()=>mapComponent?.fitView()}>Fit all</button><button class="secondary outline small" on:click={()=>mapComponent?.readableView()}>Readable zoom</button><button class="secondary outline small" on:click={()=>mapComponent?.relayout()}>Auto layout</button>{/if}<span class="workspace-mode">{presentationLabel}</span><span class="workspace-context">{contextLabel}</span></div>{/if}
<div class="map-container">{#if !filtered.nodes.length}<div class="empty">No matching devices. Broaden the host scope, types or search.</div>{:else}{#key signature+viewMode}{#if viewMode==="map"}<NetworkMap bind:this={mapComponent} graphData={filtered} viewKey={signature} mode="graph"/>{:else if viewMode==="grouped"}{#if groupingError}<div class="empty">Could not load container groups: {groupingError}</div>{:else if !groupedGraph}<div class="empty">Loading groups…</div>{:else}<NetworkMap bind:this={mapComponent} graphData={groupedGraph} viewKey={signature} mode="grouped"/>{/if}{:else}<TreeView graphData={filtered}/>{/if}{/key}{/if}</div>
</div>
{/if}</div>
<style>.map-page{display:flex;flex-direction:column;min-height:calc(100vh - 130px)}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:1rem}.eyebrow{font-size:.65rem;color:var(--pico-primary);font-weight:700;letter-spacing:.12em}.page-heading h1{font-size:1.8rem;margin:.3rem 0}.page-heading p{font-size:.8rem;color:var(--pico-muted-color);margin:0}.view-toggle{display:flex;gap:.25rem}.view-toggle button{padding:.4rem .8rem;font-size:.8rem;margin:0;background:transparent;color:var(--pico-color);border:1px solid var(--pico-muted-border-color)}.view-toggle button.active{background:var(--pico-primary-background);color:var(--pico-primary-inverse)}.map-toolbar{display:grid;grid-template-columns:1fr 1fr 1.4fr .8fr;gap:.8rem;background:var(--pico-card-background-color);padding:1rem;border:1px solid var(--pico-muted-border-color);border-radius:12px}.map-toolbar label{font-size:.7rem;margin:0}.map-toolbar input,.map-toolbar select{margin:.3rem 0 0;font-size:.8rem;height:2.6rem}.filter-row{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem 1rem;padding:.8rem 0}.filter-row>span{font-size:.7rem;font-weight:700}.filter-row label{font-size:.7rem;margin:0}.filter-row input{width:.9rem;height:.9rem}.save-row{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem}.save-row input{width:220px;margin:0;padding:.5rem .7rem;font-size:.75rem;height:2.4rem}.save-row button,.canvas-actions button,.member-picker button{padding:.45rem .7rem;font-size:.7rem;margin:0}.save-row>span{font-size:.65rem;color:var(--pico-muted-color);margin-left:auto}.view-note{font-size:.65rem;color:var(--pico-muted-color);margin:.6rem 0}.canvas-actions{display:flex;gap:.5rem;padding:.4rem 0}.map-container{position:relative;min-height:540px;height:65vh;border:1px solid var(--pico-muted-border-color);background:var(--pico-card-background-color);border-radius:12px;overflow:hidden}.empty{padding:3rem;text-align:center;color:var(--pico-muted-color)}.member-picker{padding:1rem;background:var(--pico-card-background-color);border:1px solid var(--pico-muted-border-color);border-radius:10px;margin-top:1rem}.member-picker h2{font-size:1rem}.member-picker p,.member-picker small{font-size:.7rem}.member-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));max-height:260px;overflow:auto;gap:.4rem;padding:.8rem 0}.member-list label{font-size:.75rem;margin:0}.member-list small{display:block;margin-left:1.5rem;color:var(--pico-muted-color)}@media(max-width:900px){.map-toolbar{grid-template-columns:1fr 1fr}}@media(max-width:500px){.map-toolbar{grid-template-columns:1fr}.page-heading{align-items:start}.save-row>span{margin-left:0}.map-container{min-height:450px}}.map-workspace{display:flex;flex-direction:column;min-height:0}.map-workspace.expanded{position:fixed;inset:0;z-index:1000;background:var(--pico-background-color);padding:.75rem;display:flex;flex-direction:column}.map-workspace.expanded .map-container{height:auto;min-height:0;flex:1}.expanded-toolbar{display:flex;flex-wrap:wrap;gap:.5rem;align-items:center;padding:0 0 .6rem}.expanded-toolbar button{margin:0;padding:.35rem .7rem;font-size:.72rem}.workspace-mode{font-size:.68rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--pico-primary)}.workspace-context{font-size:.7rem;color:var(--pico-muted-color);margin-left:auto}:global(body.map-expanded){overflow:hidden}@media(max-width:600px){.workspace-context{margin-left:0;width:100%}}</style>
